import pyasn1

# ASN.1 module
class ASN1Module:
    def __init__(self, asn_data):
        self.asn_data = asn_data

    def encode(self):
        return pyasn1.encode(self.asn_data)

    def decode(self, asn_string):
        return pyasn1.decode(asn_string)

# Custom ASN.1 protocol
class CustomProtocol:
    def __init__(self, protocol_id, protocol_data):
        self.protocol_id = protocol_id
        self.protocol_data = protocol_data

    def encode(self):
        return pyasn1.encode(self.protocol_data)

    def decode(self, asn_string):
        return pyasn1.decode(asn_string)

# ASN.1 module with custom protocol
class CustomASN1Module(ASN1Module):
    def __init__(self, asn_data):
        super().__init__(asn_data)
        self.custom_protocol = CustomProtocol('1.2.3', self.asn_data)

# Create an instance of the custom ASN.1 module
custom_asn1_module = CustomASN1Module(b'\x12\x34\x56\x78\x90\xab\xcd\xef')

# Encode the custom ASN.1 module
encoded_custom_asn1_module = custom_asn1_module.encode()

# Decode the encoded custom ASN.1 module
decoded_custom_asn1_module = custom_asn1_module.decode(encoded_custom_asn1_module)

# Print the custom ASN.1 protocol
print(decoded_custom_asn1_module.custom_protocol.protocol_id)  # Output: 1.2.3

