import re

class CustomRegex:
    def __init__(self):
        self.patterns = {}

    def compile_pattern(self, pattern):
        """Compile a pattern and store it in the internal dictionary"""
        self.patterns[pattern] = re.compile(pattern)

    def match(self, string):
        """Match a string against a compiled pattern"""
        return self.patterns.get(string, re.compile(string)).match(string)

    def search(self, string):
        """Search for a pattern in a string"""
        return self.patterns.get(string, re.compile(string)).search(string)

    def sub(self, string, pattern, repl):
        """Replace a pattern in a string"""
        return self.patterns.get(string, re.compile(string)).sub(string, repl)

    def findall(self, string):
        """Find all occurrences of a pattern in a string"""
        return self.patterns.get(string, re.compile(string)).findall(string)

    def escape(self, string):
        """Escape special characters in a string"""
        return re.escape(string)

# Example usage:
regex = CustomRegex()
regex.compile_pattern(r'\d{4}-\d{2}-\d{2}')

# Test the compiled pattern
print(regex.match('2022-07-25'))  # Should print: True

# Test the search function
print(regex.search('2022-07-25'))  # Should print: True

# Test the sub function
print(regex.sub('2022-07-25', r'\d{4}-\d{2}-\d{2}', '2023-07-25'))  # Should print: '2023-07-25'

# Test the findall function
print(regex.findall('2022-07-25'))  # Should print: ['2022-07-25']

# Test the escape function
print(regex.escape('abc'))  # Should print: 'abc'
