class Element:
    def __init__(self, name, attrs=None, content=None):
        self.name = name
        self.attrs = attrs if attrs else {}
        self.content = content

    def __str__(self):
        return f"<{self.name}{self.attrs}>{self.content}"


class Tag:
    def __init__(self, name, attrs=None):
        self.name = name
        self.attrs = attrs if attrs else {}

    def __str__(self):
        return f"<{self.name}{self.attrs}>"


class Parser:
    def __init__(self):
        self.current_tag = None
        self.current_tag_stack = []

    def handle_starttag(self, tag_name, attrs):
        new_tag = Tag(tag_name, attrs)
        self.current_tag_stack.append(new_tag)
        self.current_tag = new_tag

    def handle_endtag(self, tag_name):
        if self.current_tag:
            self.current_tag_stack.pop()

    def handle_data(self, data):
        if self.current_tag:
            self.current_tag.content += data

    def parse(self, html_string):
        parser = Parser()
        for line in html_string.splitlines():
            if line.startswith("<"):
                tag_name = line[1:].split()[0]
                attrs = {}
                for pair in line[1:].split(" "):
                    if pair.startswith("-"):
                        attrs[pair[1:]] = True
                    else:
                        attrs[pair] = False
                parser.handle_starttag(tag_name, attrs)
            elif line.endswith("/>"):
                parser.handle_endtag(line[0])
            else:
                parser.handle_data(line)
        if self.current_tag:
            return self.current_tag

    def get_result(self):
        return self.current_tag


# Example usage:
html_string = "<html><head><title>Test</title></head><body><p>This is a test</p></body></html>"
parser = Parser()
result = parser.parse(html_string)
print(result)
```

This code defines a recursive descent parser for the WHATWG HTML specification. It uses a stack to keep track of the current tag and the stack of opening tags. The `handle_starttag` method is called when a new tag is encountered, and the `handle_endtag` method is called when an ending tag is encountered. The `handle_data` method is called when data is encountered between tags. The `parse` method is called to parse the HTML string, and the `get_result` method is called to get the root element of the parsed HTML.

