import jsonpath
import json

class JsonPathParser:
    def __init__(self, json_string):
        self.json_string = json_string
        self.tree = self.parse_json_string()

    def parse_json_string(self):
        # Parse the JSON string into a nested dictionary
        data = json.loads(self.json_string)
        return data

    def evaluate(self, expression):
        # Evaluate the expression using the abstract syntax tree
        return self._evaluate_expression(self.tree, expression)

    def _evaluate_expression(self, tree, expression):
        # Recursively evaluate the expression
        if isinstance(tree, dict):
            # If the tree is a dictionary, evaluate the expression at the current key
            return self._evaluate_expression(tree, expression)
        elif isinstance(tree, list):
            # If the tree is a list, recursively evaluate each item
            return [self._evaluate_expression(item, expression) for item in tree]
        elif isinstance(tree, (int, float)):
            # If the tree is a number, return it as is
            return tree
        elif isinstance(tree, str):
            # If the tree is a string, evaluate the expression as a string
            return self._evaluate_expression(tree, expression)
        elif isinstance(tree, list):
            # If the tree is a list, evaluate the expression
            return self._evaluate_expression(tree, expression)
        elif isinstance(tree, tuple):
            # If the tree is a tuple, recursively evaluate each item
            return [self._evaluate_expression(item, expression) for item in tree]
        else:
            # If the tree is not a supported data type, raise an error
            raise ValueError(f"Unsupported tree type: {type(tree)}")

    def _jsonpath(self, expression):
        # Evaluate the expression using the abstract syntax tree
        return self.evaluate(self._jsonpath_helper(expression))

    def _jsonpath_helper(self, expression):
        # Recursively evaluate the expression
        if isinstance(expression, str):
            # If the expression is a string, evaluate it as a string
            return self._evaluate_expression(expression, expression)
        elif isinstance(expression, dict):
            # If the expression is a dictionary, evaluate it recursively
            return {key: self._jsonpath_helper(value) for key, value in expression.items()}
        elif isinstance(expression, list):
            # If the expression is a list, recursively evaluate each item
            return [self._jsonpath_helper(item) for item in expression]
        else:
            # If the expression is not a supported data type, raise an error
            raise ValueError(f"Unsupported expression type: {type(expression)}")

# Usage
json_string = '''
{
    "name": "John",
    "age": 30,
    "city": "New York",
    "hobbies": ["reading", "coding", "running"]
}
'''

parser = JsonPathParser(json_string)
print(parser._jsonpath('$.name'))  # Output: John
print(parser._jsonpath('$.age'))   # Output: 30
print(parser._jsonpath('$.city'))  # Output: New York
print(parser._jsonpath('$.hobbies'))  # Output: ['reading', 'coding', 'running']
print(parser._jsonpath('$.age > 25'))  # Output: 30
```

