import os
import json
import subprocess

class PreCommitHookManager:
    def __init__(self, config_file):
        self.config_file = config_file
        self.hooks = {}

    def load_config(self):
        with open(self.config_file, 'r') as f:
            return json.load(f)

    def add_hook(self, language, hook):
        self.hooks[language] = hook

    def run_hook(self, language):
        if language in self.hooks:
            return self.hooks[language]()
        else:
            return None

def create_pre_commit_hook_manager(config_file):
    manager = PreCommitHookManager(config_file)
    return manager

def main():
    config_file = 'pre_commit_hooks.json'
    manager = create_pre_commit_hook_manager(config_file)

    # Define pre-commit hooks for different languages
    manager.add_hook('python', lambda: subprocess.run(['python', '-m', 'unittest', '-v'], shell=True))
    manager.add_hook('java', lambda: subprocess.run(['javac', '-version'], shell=True))
    manager.add_hook('javascript', lambda: subprocess.run(['node', '-v'], shell=True))
    manager.add_hook('ruby', lambda: subprocess.run(['ruby', '-v'], shell=True))

    # Run the hooks during the commit process
    while True:
        language = input("Enter the language to run the hook (or 'q' to quit): ")
        if language.lower() == 'q':
            break
        hook = manager.run_hook(language)
        if hook:
            print(f"Hook ran successfully for {language}")

if __name__ == "__main__":
    main()
```

This code defines a `PreCommitHookManager` class that manages a centralized configuration file for defining pre-commit hooks and their associated languages. It also includes a simple command-line interface to run the hooks during the commit process.

The `create_pre_commit_hook_manager` function creates an instance of the `PreCommitHookManager` class with the specified configuration file.

The `main` function demonstrates how to use the `PreCommitHookManager` class by defining pre-commit hooks for different languages and running them during the commit process.

The configuration file `pre_commit_hooks.json` should contain an array of objects with the following structure:
```json
{
    "python": {
        "description": "Python-specific hook",
        "command": ["python", "-m", "unittest", "-v"]
    },
    "java": {
        "description": "Java-specific hook",
        "command": ["javac", "-version"]
    },
    "javascript": {
        "description": "JavaScript-specific hook",
        "command": ["node", "-v"]
    },
    "ruby": {
        "description": "Ruby-specific hook",
        "command": ["ruby", "-v"]
    }
}
```
Each object in the array should contain the language name as the key and a dictionary with the hook description and command as the value.

