import maxminddb

def read_maxmind_db_file(file_path):
    # Initialize the MaxMind DB file
    db = maxminddb.open(file_path, 'r')

    # Read country codes and city information from the database
    country_codes = {}
    city_info = {}

    for record in db:
        country_code = record['country_code']
        city = record['city'].split(', ')

        if country_code not in country_codes:
            country_codes[country_code] = {}

        for city in city:
            if city not in country_codes[country_code]:
                country_codes[country_code][city] = []

            country_codes[country_code][city].append(record)

    return country_codes, city_info

# Usage
file_path = 'maxminddb.db'
country_codes, city_info = read_maxmind_db_file(file_path)

for country_code, cities in country_codes.items():
    print(f"Country Code: {country_code}")
    for city, records in cities.items():
        print(f"  City: {city}")
        for record in records:
            print(f"    IP Address: {record['ip_address']}, Country: {record['country_name']}, City: {record['city_name']}")
```

Please note that you will need to install the `maxmind-db` library first by running `pip install maxmind-db` in your command prompt or terminal. Also, make sure to replace `'maxminddb.db'` with the actual path to your MaxMind DB file.

