from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from flask_bcrypt import Bcrypt
import googlemaps
import json
import uuid

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
db = SQLAlchemy(app)
gmaps = googlemaps.Client(key='YOUR_GOOGLE_MAPS_API_KEY')

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)
    role = db.Column(db.String(80), nullable=False)

    def __init__(self, username, password, role):
        self.username = username
        self.password = bcrypt.generate_password_hash(password)
        self.role = role

    def check_password(self, password):
        return bcrypt.check_password_hash(self.password, password)

class Post(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(80), nullable=False)
    content = db.Column(db.Text, nullable=False)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    user = db.relationship('User', backref=db.backref('posts', lazy=True))

    def __init__(self, title, content, user_id):
        self.title = title
        self.content = content
        self.user_id = user_id

    def to_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'content': self.content,
            'user_id': self.user_id
        }

class Comment(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.Text, nullable=False)
    post_id = db.Column(db.Integer, db.ForeignKey('post.id'), nullable=False)
    post = db.relationship('Post', backref=db.backref('comments', lazy=True))

    def __init__(self, content, post_id):
        self.content = content
        self.post_id = post_id

    def to_dict(self):
        return {
            'id': self.id,
            'content': self.content,
            'post_id': self.post_id
        }

class Chart(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(80), nullable=False)
    data = db.Column(db.Text, nullable=False)

    def __init__(self, title, data):
        self.title = title
        self.data = data

class LoginManager(LoginManager):
    def create_user(self, username, password):
        user = User(username, password, 'admin')
        db.session.add(user)
        db.session.commit()
        login_user(user)

    def authenticate(self, username, password):
        user = User.query.filter_by(username=username).first()
        if user and user.check_password(password):
            return user
        return None

    def generate_token(self, user):
        return str(user.id)

class Bcrypt:
    def generate_password_hash(self, password):
        return bcrypt.gensalt()

    def check_password_hash(self, password, hashed_password):
        return bcrypt.check_password_hash(hashed_password, password)

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    role = data.get('role')
    user = User(username, password, role)
    db.session.add(user)
    db.session.commit()
    return jsonify({'message': 'User created successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    user = LoginManager().authenticate(username, password)
    if user:
        token = user.generate_token(user)
        return jsonify({'token': token}), 200
    return jsonify({'message': 'Invalid credentials'}), 401

@app.route('/posts', methods=['GET'])
@login_required
def get_posts():
    posts = Post.query.filter_by(user_id=current_user.id).all()
    return jsonify([post.to_dict() for post in posts]), 200

@app.route('/posts', methods=['POST'])
@login_required
def create_post():
    data = request.get_json()
    title = data.get('title')
    content = data.get('content')
    user_id = current_user.id
    post = Post(title, content, user_id)
    db.session.add(post)
    db.session.commit()
    return jsonify(post.to_dict()), 201

@app.route('/comments', methods=['POST'])
@login_required
def create_comment():
    data = request.get_json()
    content = data.get('content')
    post_id = current_user.id
    comment = Comment(content, post_id)
    db.session.add(comment)
    db.session.commit()
    return jsonify(comment.to_dict()), 201

@app.route('/charts', methods=['POST'])
@login_required
def create_chart():
    data = request.get_json()
    title = data.get('title')
    data = json.loads(data.get('data'))
    chart = Chart(title, data)
    db.session.add(chart)
    db.session.commit()
    return jsonify(chart.to_dict()), 201

if __name__ == '__main__':
    app.run(debug=True)
```

This code creates a Flask-based web application with automatic CRUD operations, security features, and Google Charts integration. It includes a `User` model, a `Post` model, a `Comment` model, and a `Chart` model. The application uses Flask-SQLAlchemy for database operations, Flask-Login for user authentication, and Flask-Bcrypt for password hashing. Google Maps API is used to create a chart.
